"url": "https://collections.vam.ac.uk/item/O152496/",
"desc": "Figure, glazed porcelain, China, 1965-1975, Chairman Mao Figure, moulded in two vertical sections; remains of smoothed mould line still visible down sides. The upraised arm, book and left hand have probably been added as separate sections, and the plinth added; a lot surface finishing also carried out. The figure shows a middle-aged Chairman Mao in a Sun Yatsen-style jacket suit, standing upright with right arm raise",
